"""Build collection lookbooks with six background choices per design."""
from pathlib import Path
import json,html,urllib.parse
R=Path(__file__).resolve().parent.parent
rows=json.loads((R/'assets/celestial-patterns.json').read_text())
for row in rows:
 for look in row['looks']:assert (R/look['preview']).is_file(), 'Render case preview first: '+look['preview']
e=lambda s:html.escape(str(s),quote=True)
sections=[('celestial-creatures.html','Zodiac Creatures','Your sign.<br>In full character.','Twelve richly detailed animals, figures and symbols. Choose a background that feels like you.',['Zodiac Creatures']),('tarot.html','Tarot','A little magic.<br>Every day.','The Sun, Moon, Star and Lovers. Four original illustrations with a background for every mood.',['Tarot']),('pattern-studio.html','Pattern Studio','Dots. Lines.<br>Your kind of rhythm.','Clean geometry, playful proportions and colors that work together. The pattern stays true; you choose the background.',['Polka dots','Stripes & waves'])]
for filename,title,headline,desc,cats in sections:
 p=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | Keepsake Printing Co.</title><meta name="description" content="{e(desc)} Clear cases personalized and purchased in store."><link rel="icon" href="assets/favicon.svg"><link rel="stylesheet" href="assets/homepage.css"><link rel="stylesheet" href="assets/shop-menu.css?v=start-case-1"><link rel="stylesheet" href="assets/case-zoom.css"><link rel="stylesheet" href="assets/new-prints.css"><link rel="stylesheet" href="assets/collection-backgrounds.css"><script src="assets/shop-menu.js?v=celestial-2" defer></script></head><body><a class="skip-link" href="#main">Skip to content</a><div class="announcement"><span>PERSONALIZED IN STORE · EVERY CASE DESIGN $44.99</span><a href="index.html#stores">Find your counter ↗</a></div><header class="home-header"><a class="wordmark" href="index.html" aria-label="Keepsake home"><img src="assets/favicon.svg" width="40" height="40" alt=""><span>KEEPSAKE<small>PRINTING CO.</small></span></a><nav class="desktop-nav" aria-label="Main navigation"><a href="gallery.html">Phone cases</a><a href="slates.html">Photo slates</a><a href="index.html#how-it-works">How it works</a><a href="index.html#stores">Visit us</a></nav><a class="header-cta" href="instore/">In-store browsing ↗</a></header><main id="main" class="fresh-page"><header class="fresh-intro"><p class="eyebrow">{e(title)}</p><h1>{headline}</h1><p>{e(desc)}</p><p class="fresh-note">Five backgrounds + Artwork only. Tap a case to zoom.<br>Digital previews on clear cases, shown on iPhone 17 Pro Max. Choose your phone in the studio.</p></header><nav class="fresh-nav" aria-label="Explore collections"><a href="celestial-creatures.html">Zodiac Creatures</a><a href="tarot.html">Tarot</a><a href="pattern-studio.html#polka-dots">Polka dots</a><a href="pattern-studio.html#stripes-waves">Lines &amp; stripes</a><a href="gallery.html?cat=Zodiac">Original Zodiac</a></nav>'''
 for cat in cats:
  anchor={'Polka dots':'polka-dots','Stripes & waves':'stripes-waves'}.get(cat,'designs')
  p+=f'<section class="fresh-section" id="{anchor}"><div class="fresh-heading"><h2>{e(cat)}</h2><a class="fresh-browse" href="gallery.html?cat={urllib.parse.quote(cat)}">Browse all {e(cat)} →</a></div><div class="fresh-grid">'
  for r in [r for r in rows if r['category']==cat]:
   title=r['title'].replace(' · Celestial Creature','');look=r['looks'][0];href='customizer.html?design='+r['file']+'&view=phone';identifier=Path(r['file']).stem
   p+=f'<article class="fresh-card background-card" data-design="{e(r["file"])}" data-title="{e(title)}"><a data-preview-link class="fresh-image" href="{e(href)}" aria-label="Enlarge {e(title)} · {e(look["name"])}"><img loading="lazy" decoding="async" width="600" height="1200" src="{look["preview"]}" alt="{e(title)} on a clear case · {e(look["name"])} background"></a><div class="fresh-card-title"><h3>{e(title)}</h3><span>$44.99</span></div><p class="background-status" id="{identifier}-status" aria-live="polite">Background: {e(look["name"])}</p><div class="background-options" role="group" aria-label="Background for {e(title)}">'
   for choice in r['looks']:
    p+=f'<button type="button" data-variant="{choice["id"]}" data-name="{e(choice["name"])}" data-preview="{choice["preview"]}" aria-label="{e(choice["name"])}" aria-pressed="{str(choice["id"]=="original").lower()}" title="{e(choice["name"])}"><span style="--swatch:{choice["background"]}" class="{("clear-swatch" if choice["id"]=="c5" else "")}"></span></button>'
   p+=f'</div><a class="fresh-customize" href="{e(href)}">Make it yours <span aria-hidden="true">↗</span></a></article>'
  p+='</div></section>'
 p+='''<footer class="fresh-footer"><h2>Make it personal.</h2><p>The illustration stays the same in every color. Choose Artwork only to let your phone show through the clear case.</p><p>Golden tones are printed colors, not metallic foil. Zodiac Creatures and Tarot feature original AI-assisted illustrations. The geometric patterns are original vector artwork.</p><p><a href="gallery.html?cat=Zodiac">Explore the original Zodiac collection</a> · <a href="new-prints.html">More fresh prints</a> · <a href="index.html#stores">Find your store</a></p></footer></main><script src="assets/collection-backgrounds.js"></script><script src="assets/case-zoom.js"></script></body></html>'''
 (R/filename).write_text(p+'\n')
print('Built 3 collection pages with 32 designs')
